l class="master-check"><input type="checkbox" name="is_active" value="1" checked> Aktif</label></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Tambah pilihan</button></div></form></dialog><?php endif; ?><?php endif; ?>
