99" required value="<?= $row->asset_quantity===NULL?'':(int)$row->asset_quantity ?>"></label><label class="span-2">Link Google Spreadsheet CTT <small>opsional</small><input type="url" name="spreadsheet_url" maxlength="500" value="<?= e($row->spreadsheet_url) ?>"></label><?php endif; ?><label class="span-2">Deskripsi<input name="description" maxlength="255" value="<?= e($row->description) ?>"></label></div><?php if ($group->allow_create): ?><label class="master-check"><input type="checkbox" name="is_active" value="1"<?= $row->is_active?' checked':'' ?><?= $this->metro->can($current_user->id,'masters.status')?'':' disabled' ?>> Tersedia sebagai pilihan aktif</label><?php endif; ?></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan perubahan</button></div></form></dialog><?php endif; ?><?php endforeach; ?>
